import { useEffect, useMemo, useState } from 'react';
import { Plus, MapPin } from 'lucide-react';
import { Button, Card, Input, Modal, Pill, useToast } from '@nako/ui';
import { formatMoney, getRegion } from '@nako/core';
import { useAuthStore } from '@/stores/auth';
import { useRegionStore } from '@/stores/region';
import { supabase } from '@/lib/supabase';
import { iconsForIndustry } from '@/lib/industry-icons';

interface FixedAsset {
  id: string;
  business_id: string;
  name: string;
  category: string | null;
  cost: number;
  currency: 'AED' | 'SAR' | 'USD';
  acquired_date: string;
  location: string | null;
  status: 'in_service' | 'retired' | 'disposed';
  depreciation_method: string | null;
  useful_life_years: number | null;
  accumulated_depreciation: number;
  notes: string | null;
}

export default function FixedAssets() {
  const business = useAuthStore((s) => s.business)!;
  const regionCode = useRegionStore((s) => s.code);
  const toast = useToast();
  const Icon = iconsForIndustry(business.industry).assets;
  const [assets, setAssets] = useState<FixedAsset[]>([]);
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({
    name: '',
    category: '',
    cost: 0,
    currency: (getRegion(regionCode).currencyCode as FixedAsset['currency']) || 'AED',
    acquired_date: '',
    location: '',
    useful_life: 10,
  });

  useEffect(() => {
    void load();
  }, [business.id]);

  async function load() {
    const { data } = await supabase
      .from('fixed_assets')
      .select('*')
      .eq('business_id', business.id)
      .order('acquired_date', { ascending: false });
    setAssets((data ?? []) as FixedAsset[]);
  }

  async function create() {
    if (!form.name || !form.cost) {
      toast.show('Name and cost are required', { tone: 'warning' });
      return;
    }
    await supabase.from('fixed_assets').insert({
      business_id: business.id,
      name: form.name,
      category: form.category || null,
      cost: Number(form.cost),
      currency: form.currency,
      acquired_date: form.acquired_date || new Date().toISOString().slice(0, 10),
      location: form.location || null,
      status: 'in_service',
      depreciation_method: 'straight_line',
      useful_life_years: Number(form.useful_life) || 10,
      accumulated_depreciation: 0,
      notes: null,
    });
    toast.show('Asset added.', { tone: 'success' });
    setOpen(false);
    setForm({
      name: '',
      category: '',
      cost: 0,
      currency: (getRegion(regionCode).currencyCode as FixedAsset['currency']) || 'AED',
      acquired_date: '',
      location: '',
      useful_life: 10,
    });
    void load();
  }

  // Group by category for the register view
  const grouped = useMemo(() => {
    const m = new Map<string, FixedAsset[]>();
    for (const a of assets) {
      const key = a.category ?? 'Uncategorised';
      if (!m.has(key)) m.set(key, []);
      m.get(key)!.push(a);
    }
    return Array.from(m.entries()).sort(([a], [b]) => a.localeCompare(b));
  }, [assets]);

  const homeCurrency = getRegion(regionCode).currencyCode;
  const totals = useMemo(() => {
    // Sum home-currency cost only (don't FX-convert foreign currencies).
    let home = 0;
    let foreign = 0;
    for (const a of assets) {
      if (a.currency === homeCurrency) home += a.cost;
      else foreign += a.cost;
    }
    return { home, foreign };
  }, [assets, homeCurrency]);

  /** Straight-line monthly depreciation per asset. Zero when life or method missing. */
  function monthlyDepreciation(a: FixedAsset): number {
    if (!a.useful_life_years || a.useful_life_years <= 0) return 0;
    if (a.depreciation_method && a.depreciation_method !== 'straight_line') return 0;
    return Math.max(0, a.cost / (a.useful_life_years * 12));
  }

  /** Carrying value = cost - accumulated_depreciation, floored at zero. */
  function carryingValue(a: FixedAsset): number {
    return Math.max(0, a.cost - (a.accumulated_depreciation || 0));
  }

  const totalMonthlyDep = assets
    .filter((a) => a.status === 'in_service' && a.currency === homeCurrency)
    .reduce((s, a) => s + monthlyDepreciation(a), 0);

  return (
    <main className="mx-auto max-w-3xl px-4 py-4 md:px-6 md:py-6">
      <div className="mb-4 flex items-center justify-between">
        <h1 className="font-display flex items-center gap-2 text-2xl">
          <Icon size={22} /> Fixed Asset Register
        </h1>
        <Button size="sm" leftIcon={<Plus size={16} />} onClick={() => setOpen(true)}>
          Add asset
        </Button>
      </div>

      {/* Totals */}
      <div className="mb-4 grid grid-cols-3 gap-3">
        <Card compact>
          <p className="text-muted text-xs">Cost ({homeCurrency})</p>
          <p className="tnum font-mono text-xl">{formatMoney(totals.home, regionCode)}</p>
        </Card>
        <Card compact>
          <p className="text-muted text-xs">Cost (foreign)</p>
          <p className="tnum font-mono text-xl">
            {totals.foreign > 0 ? `~${formatMoney(totals.foreign, regionCode)}` : '—'}
          </p>
          <p className="text-muted text-[10px]">
            Foreign-currency assets shown at carrying cost, not FX-converted
          </p>
        </Card>
        <Card compact>
          <p className="text-muted text-xs">Monthly depreciation</p>
          <p className="tnum font-mono text-xl">{formatMoney(totalMonthlyDep, regionCode)}</p>
          <p className="text-muted text-[10px]">Straight-line, in-service assets only</p>
        </Card>
      </div>

      {assets.length === 0 ? (
        <Card className="py-10 text-center">
          <Icon size={32} className="text-muted mx-auto mb-3 opacity-50" />
          <p className="text-muted mb-4">No fixed assets registered yet.</p>
          <Button onClick={() => setOpen(true)} leftIcon={<Plus size={16} />}>
            Register your first asset
          </Button>
        </Card>
      ) : (
        <div className="space-y-4">
          {grouped.map(([category, list]) => (
            <div key={category}>
              <h2 className="text-muted mb-2 text-xs font-semibold uppercase tracking-wider">
                {category}
              </h2>
              <div className="space-y-2">
                {list.map((a) => (
                  <Card key={a.id} compact>
                    <div className="flex items-start justify-between gap-3">
                      <div className="min-w-0 flex-1">
                        <p className="font-medium">{a.name}</p>
                        <p className="text-muted text-xs">
                          Acquired {a.acquired_date}
                          {a.useful_life_years ? ` · ${a.useful_life_years}y life` : ''}
                          {a.location && (
                            <>
                              {' · '}
                              <MapPin size={10} className="inline" /> {a.location}
                            </>
                          )}
                        </p>
                      </div>
                      <div className="text-right">
                        <p className="tnum font-mono text-sm font-semibold">
                          {a.currency === homeCurrency
                            ? formatMoney(a.cost, regionCode)
                            : `${a.currency} ${a.cost.toLocaleString('en-US', {
                                minimumFractionDigits: 2,
                                maximumFractionDigits: 2,
                              })}`}
                        </p>
                        {a.currency === homeCurrency && (a.accumulated_depreciation || 0) > 0 && (
                          <p className="tnum text-muted font-mono text-[10px]">
                            NBV {formatMoney(carryingValue(a), regionCode)}
                          </p>
                        )}
                        {a.currency === homeCurrency &&
                          a.status === 'in_service' &&
                          monthlyDepreciation(a) > 0 && (
                            <p className="text-muted font-mono text-[10px]">
                              {formatMoney(monthlyDepreciation(a), regionCode)} / mo
                            </p>
                          )}
                        <Pill
                          tone={
                            a.status === 'in_service'
                              ? 'green'
                              : a.status === 'retired'
                                ? 'neutral'
                                : 'red'
                          }
                          className="mt-1"
                        >
                          {a.status.replace('_', ' ')}
                        </Pill>
                      </div>
                    </div>
                  </Card>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      <Modal open={open} onClose={() => setOpen(false)} title="Register fixed asset">
        <div className="space-y-3">
          <Input
            label="Asset name"
            value={form.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
          />
          <Input
            label="Category"
            placeholder="Vehicles, Kitchen equipment, IT, Buildings…"
            value={form.category}
            onChange={(e) => setForm({ ...form, category: e.target.value })}
          />
          <div className="grid grid-cols-3 gap-2">
            <div className="col-span-2">
              <Input
                label="Cost"
                type="number"
                numeric
                value={form.cost || ''}
                onChange={(e) => setForm({ ...form, cost: Number(e.target.value) })}
              />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-sm font-medium">Currency</label>
              <select
                value={form.currency}
                onChange={(e) =>
                  setForm({ ...form, currency: e.target.value as FixedAsset['currency'] })
                }
                className="min-h-tap rounded-btn border-line border bg-white px-3"
              >
                <option value="AED">AED</option>
                <option value="SAR">SAR</option>
                <option value="USD">USD</option>
              </select>
            </div>
          </div>
          <Input
            label="Acquired date"
            type="date"
            value={form.acquired_date}
            onChange={(e) => setForm({ ...form, acquired_date: e.target.value })}
          />
          <Input
            label="Location (optional)"
            placeholder="Branch, room, vehicle reg…"
            value={form.location}
            onChange={(e) => setForm({ ...form, location: e.target.value })}
          />
          <Input
            label="Useful life (years)"
            type="number"
            numeric
            value={form.useful_life || ''}
            onChange={(e) => setForm({ ...form, useful_life: Number(e.target.value) })}
          />
          <Button full onClick={create}>
            Register asset
          </Button>
        </div>
      </Modal>
    </main>
  );
}
