/**
 * Multi-region configuration — Rizq (رِزق), Gulf / GCC edition.
 *
 * Rizq is the Gulf-market accounting product. The engine swaps VAT rules,
 * corporate tax / Zakat, social-insurance contributions, currency (incl.
 * 3-decimal Gulf dinars), and the local tax authority per tenant.
 *
 * Sources (current as of 2026):
 *   - UAE (AE):     FTA — VAT 5%, Corporate Tax 9% (from Jun 2023), EmaraTax
 *   - Saudi (SA):   ZATCA — VAT 15%, CIT 20% + Zakat 2.5%, FATOORA e-invoicing
 *   - Qatar (QA):   GTA — VAT not yet in force, CIT 10% on foreign profit
 *   - Bahrain (BH): NBR — VAT 10%, no general CIT (DMTT 15% large MNEs)
 *   - Kuwait (KW):  KTA/MoF — VAT not yet in force, CIT 15% on foreign profit
 *   - Oman (OM):    OTA — VAT 5%, CIT 15% (SME 3%)
 *
 * GCC states levy NO personal income tax. The `paye` table is therefore
 * empty for every region (the PAYE helpers return 0). Payroll deductions
 * are modelled as social-insurance contributions (GOSI / GPSSA / PASI /
 * SIO / PIFSS) via `socialInsurance`, which generally apply to GCC
 * nationals only.
 */
export type RegionCode = 'AE' | 'SA' | 'QA' | 'BH' | 'KW' | 'OM';

export interface PayeBracket {
  threshold: number;
  rate: number;
  cumulative: number;
}

/** Social-insurance contribution (GOSI, GPSSA, PASI, SIO, PIFSS …). */
export interface PayrollLevy {
  name: string;
  rate: number;
  employeeShare: number;
  employerShare: number;
  monthlyCeiling?: number;
  /** True where the scheme covers GCC nationals only (expats excluded). */
  nationalsOnly?: boolean;
}

export interface WithholdingTax {
  category: string;
  rate: number;
}

export interface RegionConfig {
  code: RegionCode;
  displayName: string;
  /** Arabic display name. */
  displayNameAr: string;
  currencyCode: string;
  currencySymbol: string;
  /** Arabic currency symbol. */
  currencySymbolAr: string;
  /** Minor-unit name (fils, baisa, halala). */
  minorUnit: string;
  /** How many decimal places the currency uses (2, or 3 for BHD/KWD/OMR). */
  currencyDecimals: number;
  locale: string;
  vat: {
    rate: number;
    registrationThreshold: number;
    returnForm: string;
    /** True for states that have announced but not yet implemented VAT. */
    notLiveYet?: boolean;
    /** E-invoicing programme name, where mandated. */
    eInvoicing?: string;
  };
  corporateTax: {
    standard: number;
    small?: number;
    smallTurnoverCeiling?: number;
    /** Profit threshold below which CIT is 0 (UAE small-business relief). */
    exemptBelow?: number;
    /** Zakat rate on the Saudi/GCC-owned share, where it applies. */
    zakat?: number;
  };
  /** Personal income tax — none across the GCC (kept for parity with the engine). */
  personalIncomeTax: boolean;
  paye: PayeBracket[];
  /** Social-insurance schemes (alias surfaced as payrollLevies for the engine). */
  socialInsurance: PayrollLevy[];
  withholding: WithholdingTax[];
  languages: Array<{ code: string; name: string; nativeName: string }>;
  fiscalYearStartMonth: number;
  taxAuthority: string;
  blurb: string;
}

