export const REGIONS: Record<RegionCode, RegionConfig> = { AE, SA, QA, BH, KW, OM };
export const REGION_CODES: RegionCode[] = ['AE', 'SA', 'QA', 'BH', 'KW', 'OM'];
export const DEFAULT_REGION: RegionCode = 'AE';

export function getRegion(code: string | null | undefined): RegionConfig {
  if (!code) return REGIONS[DEFAULT_REGION];
  const cfg = REGIONS[code as RegionCode];
  return cfg ?? REGIONS[DEFAULT_REGION];
}
