/**
 * VAT / consumption-tax calculations — Gulf / GCC edition.
 *
 * Region-aware standard rates:
 *   - UAE (AE):     5%   (FTA)
 *   - Saudi (SA):   15%  (ZATCA)
 *   - Qatar (QA):   0%   (VAT announced, not yet in force)
 *   - Bahrain (BH): 10%  (NBR)
 *   - Kuwait (KW):  0%   (VAT announced, not yet in force)
 *   - Oman (OM):    5%   (OTA)
 *
 * The standalone helpers default to the UAE 5% rate so call sites that
 * don't pass a region still behave sensibly in the home market.
 */

import { getRegion, type RegionCode } from './region';

/** Default standard VAT rate (UAE, 5%). */
export const DEFAULT_VAT_RATE = 0.05;

/** Look up the standard VAT rate for a region. */
export function vatRateFor(region: RegionCode | string): number {
  return getRegion(region).vat.rate;
}

/** VAT-exclusive amount + VAT = VAT-inclusive amount. */
export function addVat(
  net: number,
  rate: number = DEFAULT_VAT_RATE,
): {
  net: number;
  vat: number;
  gross: number;
} {
  const vat = round2(net * rate);
  return { net: round2(net), vat, gross: round2(net + vat) };
}

/** Strip VAT out of a VAT-inclusive total. */
export function stripVat(
  gross: number,
  rate: number = DEFAULT_VAT_RATE,
): {
  net: number;
  vat: number;
  gross: number;
} {
  const net = round2(gross / (1 + rate));
  const vat = round2(gross - net);
  return { net, vat, gross: round2(gross) };
}

/** Standard VAT rate for the home market on a given date (currently flat 5%). */
export function rateForDate(_date: Date): number {
  return DEFAULT_VAT_RATE;
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}
