// Domain types — keep in sync with supabase/migrations/0001_initial_schema.sql

export type Uuid = string;
export type Iso8601 = string;
export type IsoDate = string; // YYYY-MM-DD

export type SubscriptionTier = 'free' | 'smart' | 'pro' | 'enterprise';
export type Language = 'en' | 'tn';
export type AccountType = 'asset' | 'liability' | 'equity' | 'income' | 'expense';
export type JournalSource =
  | 'receipt'
  | 'sale'
  | 'purchase'
  | 'manual'
  | 'bank'
  | 'payroll'
  | 'adjustment';
export type OcrStatus = 'pending' | 'processing' | 'completed' | 'failed' | 'manual';
export type OcrTier = 0 | 1 | 2 | 3; // 0=manual, 1=template, 2=flash, 3=pro
export type InvoiceStatus = 'draft' | 'sent' | 'paid' | 'partial' | 'overdue' | 'cancelled';
export type ReminderType = 'vat' | 'paye' | 'income_tax' | 'salary' | 'supplier' | 'custom';
export type ReminderStatus = 'pending' | 'done' | 'dismissed' | 'overdue';

