/** Industry strings that gate the Patient Management module in the UI. */
export const HEALTHCARE_INDUSTRIES = [
  'Healthcare / Doctor',
  'Healthcare / Dentist',
  'Healthcare / Pharmacist',
  'Healthcare / Clinic or Small Hospital',
] as const;

export function isHealthcareBusiness(industry: string | null): boolean {
  if (!industry) return false;
  // Prefix match so seeded values like "Healthcare / Dental" still trip the
  // gate alongside the canonical Doctor / Dentist / Pharmacist / Clinic ones.
  return industry.toLowerCase().startsWith('healthcare');
}
