import { useEffect, useState } from 'react';
import { Lock, Plus, Send } from 'lucide-react';
import { Button, Card, Input, Modal, Pill, useToast } from '@nako/ui';
import { addVat, formatMoney } from '@nako/core';
import type { Invoice, InvoiceStatus } from '@nako/types';
import { useAuthStore } from '@/stores/auth';
import { useRegionStore } from '@/stores/region';
import { supabase } from '@/lib/supabase';

interface CustomerLite {
  id: string;
  name: string;
  on_hold: boolean;
  hold_reason: string | null;
}

const STATUS_TONE: Record<InvoiceStatus, 'green' | 'red' | 'neutral' | 'accent' | 'blue'> = {
  draft: 'neutral',
  sent: 'blue',
  paid: 'green',
  partial: 'accent',
  overdue: 'red',
  cancelled: 'neutral',
};

export default function Invoices() {
  const business = useAuthStore((s) => s.business)!;
  const regionCode = useRegionStore((s) => s.code);
  const regionConfig = useRegionStore((s) => s.config);
  const toast = useToast();
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [customers, setCustomers] = useState<CustomerLite[]>([]);
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({
    customer_id: '',
    customer_name: '',
    subtotal: 0,
    vat: false,
    due_date: '',
    notes: '',
  });

  useEffect(() => {
    void load();
  }, [business.id]);

  async function load() {
    const [{ data: inv }, { data: cust }] = await Promise.all([
      supabase
        .from('invoices')
        .select('*')
        .eq('business_id', business.id)
        .order('issue_date', { ascending: false }),
      supabase
        .from('customers')
        .select('id, name, on_hold, hold_reason')
        .eq('business_id', business.id)
        .order('name'),
    ]);
    setInvoices(inv ?? []);
    setCustomers((cust ?? []) as CustomerLite[]);
  }

  const selectedCustomer = customers.find((c) => c.id === form.customer_id) ?? null;
  const isHeld = selectedCustomer?.on_hold ?? false;

  async function create() {
    if (!form.customer_name || !form.subtotal) {
      toast.show('Customer name and subtotal required', { tone: 'warning' });
      return;
    }
    if (isHeld) {
      toast.show(
        `${selectedCustomer?.name} is on credit hold (${selectedCustomer?.hold_reason ?? 'reason unspecified'}). Release the hold from Customers before invoicing.`,
        { tone: 'error', durationMs: 5000 },
      );
      return;
    }
    const v = form.vat
      ? addVat(form.subtotal)
      : { net: form.subtotal, vat: 0, gross: form.subtotal };

    // Claim the next invoice number atomically (no collisions across tabs/users).
    const { data: seq, error: seqErr } = await supabase.rpc('next_invoice_number', {
      p_business_id: business.id,
    });
    if (seqErr || typeof seq !== 'number') {
      toast.show(seqErr?.message ?? 'Could not allocate an invoice number — try again.', {
        tone: 'error',
      });
      return;
    }
    const yyyy = new Date().getFullYear();
    const number = `INV-${yyyy}-${String(seq).padStart(5, '0')}`;
    const { error } = await supabase.from('invoices').insert({
      business_id: business.id,
      invoice_number: number,
      customer_name: form.customer_name,
      customer_id: form.customer_id || null,
      issue_date: new Date().toISOString().slice(0, 10),
      due_date: form.due_date || null,
      subtotal: v.net,
      vat_amount: v.vat,
      total: v.gross,
      status: 'draft',
      notes: form.notes || null,
    });
    if (error) {
      toast.show(error.message, { tone: 'error' });
      return;
    }
    toast.show('Invoice created.', { tone: 'success' });
    setOpen(false);
    // Form reset moved to dedicated block below for type-correctness
    setForm({
      customer_id: '',
      customer_name: '',
      subtotal: 0,
      vat: false,
      due_date: '',
      notes: '',
    });
    void load();
  }

  async function markPaid(inv: Invoice) {
    await supabase
      .from('invoices')
      .update({ status: 'paid', paid_amount: inv.total })
      .eq('id', inv.id);
    toast.show('Marked paid.', { tone: 'success' });
    void load();
  }

  return (
    <main className="mx-auto max-w-3xl px-4 py-4 md:px-6 md:py-6">
      <div className="mb-4 flex items-center justify-between">
        <h1 className="font-display text-2xl">Invoices</h1>
        <Button leftIcon={<Plus size={16} />} onClick={() => setOpen(true)} size="sm">
          New
        </Button>
      </div>

      {invoices.length === 0 ? (
        <Card className="py-10 text-center">
          <Send size={32} className="text-muted mx-auto mb-3 opacity-50" />
          <p className="text-muted mb-4">No invoices yet — issue your first one.</p>
          <Button onClick={() => setOpen(true)} leftIcon={<Plus size={16} />}>
            Create first invoice
          </Button>
        </Card>
      ) : (
        <div className="space-y-2">
          {invoices.map((inv) => (
            <Card key={inv.id} compact className="flex items-center justify-between">
              <div>
                <p className="font-medium">{inv.customer_name}</p>
                <p className="text-muted font-mono text-xs">{inv.invoice_number}</p>
                <p className="text-muted text-xs">Due {inv.due_date ?? '—'}</p>
              </div>
              <div className="text-right">
                <p className="font-mono">{formatMoney(inv.total, regionCode)}</p>
                <Pill tone={STATUS_TONE[inv.status]} className="mt-1">
                  {inv.status}
                </Pill>
                {inv.status !== 'paid' && (
                  <button
                    onClick={() => markPaid(inv)}
                    className="text-accent ml-auto mt-1 block text-xs"
                  >
                    Mark paid
                  </button>
                )}
              </div>
            </Card>
          ))}
        </div>
      )}

      <Modal open={open} onClose={() => setOpen(false)} title="New invoice">
        <div className="space-y-3">
          {customers.length > 0 && (
            <div className="flex flex-col gap-1">
              <label className="text-sm font-medium">Customer</label>
              <select
                value={form.customer_id}
                onChange={(e) => {
                  const id = e.target.value;
                  const c = customers.find((x) => x.id === id);
                  setForm({
                    ...form,
                    customer_id: id,
                    customer_name: c ? c.name : form.customer_name,
                  });
                }}
                className="min-h-tap rounded-btn border-line border bg-white px-3"
              >
                <option value="">— pick a customer or type a name below —</option>
                {customers.map((c) => (
                  <option key={c.id} value={c.id} disabled={c.on_hold}>
                    {c.name}
                    {c.on_hold ? ' · ON HOLD' : ''}
                  </option>
                ))}
              </select>
            </div>
          )}

          {isHeld && (
            <div className="bg-red/10 text-red rounded-card flex gap-2 p-3 text-xs">
              <Lock size={14} className="shrink-0" />
              <div>
                <p className="font-semibold">{selectedCustomer?.name} is on credit hold</p>
                <p>{selectedCustomer?.hold_reason ?? 'Reason not recorded'}.</p>
                <p>Release the hold from Customers before invoicing this account.</p>
              </div>
            </div>
          )}

          <Input
            label="Customer name (override)"
            value={form.customer_name}
            onChange={(e) => setForm({ ...form, customer_name: e.target.value })}
          />
          <Input
            label={`Subtotal (${regionConfig.currencyCode}, before VAT)`}
            type="number"
            numeric
            value={form.subtotal || ''}
            onChange={(e) => setForm({ ...form, subtotal: Number(e.target.value) })}
            leftAddon={regionConfig.currencySymbol}
          />
          <label className="flex items-center gap-2 text-sm">
            <input
              type="checkbox"
              checked={form.vat}
              onChange={(e) => setForm({ ...form, vat: e.target.checked })}
            />
            Add {(regionConfig.vat.rate * 100).toFixed(0)}% VAT
          </label>
          <Input
            label="Due date"
            type="date"
            value={form.due_date}
            onChange={(e) => setForm({ ...form, due_date: e.target.value })}
          />
          <Input
            label="Notes (optional)"
            value={form.notes}
            onChange={(e) => setForm({ ...form, notes: e.target.value })}
          />
          <Button full onClick={create} disabled={isHeld} leftIcon={<Send size={16} />}>
            Create invoice
          </Button>
        </div>
      </Modal>
    </main>
  );
}
