/**
 * Money helpers — Gulf / GCC edition.
 *
 * Amounts are stored as decimal numbers in the major unit (dirham, riyal,
 * dinar). Formatters wrap Intl.NumberFormat keyed on the region's locale
 * and decimal precision, so the same code renders "AED 1,234.00" for the
 * UAE and "BD 1,234.500" for Bahrain (the Bahraini dinar has 1,000 fils,
 * i.e. three decimal places — likewise the Kuwaiti dinar and Omani rial).
 */

import { getRegion, type RegionCode } from './region';

/** Minor units per major unit for a region (1000 for 3-dp Gulf dinars, else 100). */
export function minorPerFor(region: RegionCode | string): number {
  return Math.pow(10, getRegion(region).currencyDecimals);
}

/** Convert a major-unit decimal to integer minor units. Rounds half-up. */
export function toMinorUnits(amount: number, minorPer = 100): number {
  return Math.round(amount * minorPer);
}

/** Convert integer minor units back to the major decimal unit. */
export function toMajorUnits(minor: number, minorPer = 100): number {
  return minor / minorPer;
}

/**
 * Region-aware money formatter — "AED 1,234.00", "SR 1,234.00",
 * "BD 1,234.500" (Bahrain · 3 decimals).
 */
export function formatMoney(
  amount: number,
  region: RegionCode | string = 'AE',
  opts: { withSymbol?: boolean } = {},
): string {
  const cfg = getRegion(region);
  const withSymbol = opts.withSymbol ?? true;
  const formatter = new Intl.NumberFormat('en-US', {
    style: 'decimal',
    minimumFractionDigits: cfg.currencyDecimals,
    maximumFractionDigits: cfg.currencyDecimals,
  });
  const formatted = formatter.format(amount);
  return withSymbol ? `${cfg.currencySymbol} ${formatted}` : formatted;
}

/** Compact form for KPI cards: "AED 15.3k", "SR 1.2M". */
export function formatMoneyCompact(amount: number, region: RegionCode | string = 'AE'): string {
  const cfg = getRegion(region);
  const sym = cfg.currencySymbol;
  const abs = Math.abs(amount);
  const sign = amount < 0 ? '-' : '';
  if (abs >= 1_000_000) return `${sign}${sym} ${(abs / 1_000_000).toFixed(1)}M`;
  if (abs >= 1_000) return `${sign}${sym} ${(abs / 1_000).toFixed(1)}k`;
  return formatMoney(amount, region);
}
