export type DictKey = keyof typeof dict;

/**
 * Look up a localised string with English fallback.
 * Use `makeT(lang)` to create a bound translator for a component.
 */
export function t(key: DictKey, lang: Lang = 'en'): string {
  const entry = dict[key];
  if (!entry) return String(key);
  return entry[lang] ?? entry.en;
}

export function makeT(lang: Lang) {
  return (key: DictKey) => t(key, lang);
}

/** All supported language codes — used by the language picker. */
export const SUPPORTED_LANGS: Lang[] = ['en', 'ar'];

/** True for right-to-left languages. */
export function isRtl(lang: Lang): boolean {
  return lang === 'ar';
}

/** Human label for a language code. */
export function langLabel(lang: Lang): string {
  switch (lang) {
    case 'en':
      return 'English';
    case 'ar':
      return 'العربية';
  }
}
