/** Providers operational in the given region (includes regional BNPL by default). */
export function providersForRegion(
  region: RegionCode,
  opts: { includeAggregators?: boolean } = {},
): MobileMoneyProvider[] {
  const includeAggregators = opts.includeAggregators ?? true;
  return MOBILE_MONEY_PROVIDERS.filter(
    (p) => p.regions.includes(region) && (includeAggregators || !p.aggregator),
  );
}
