import { useEffect, useMemo, useState } from 'react';
import { Download, FileText, Landmark, Lock, Users as UsersIcon } from 'lucide-react';
import { Button, Card, Pill, useToast } from '@nako/ui';
import { buildProfitLoss, formatMoney, monthlyPaye, type RegionConfig } from '@nako/core';
import type { Account, JournalEntry, JournalLine } from '@nako/types';
import { useAuthStore } from '@/stores/auth';
import { useRegionStore } from '@/stores/region';
import { supabase } from '@/lib/supabase';

interface PayeEmployee {
  id: string;
  name: string;
  national_id: string | null;
  basic_salary: number;
  allowances: { transport?: number; housing?: number; other?: number };
  deductions: { pension_employee?: number; medical_aid?: number; loan?: number; other?: number };
  is_active: boolean;
}

interface PayeRow {
  name: string;
  national_id: string;
  gross: number;
  pension: number;
  taxable: number;
  paye: number;
}

const monthName = (m: number) =>
  ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][m] ?? '';

interface Vat002Result {
  business_name: string;
  vat_number: string | null;
  period_start: string;
  period_end: string;
  output_vat: number;
  input_vat: number;
  net_payable: number;
  generated_at: string;
}

export default function BURS() {
  const business = useAuthStore((s) => s.business)!;
  const regionCode = useRegionStore((s) => s.code);
  const regionConfig = useRegionStore((s) => s.config);
  const taxAuth = regionConfig.taxAuthority;
  const toast = useToast();
  const isPaid = business.tier !== 'free';
  const isVat = business.vat_registered;

  const [from, setFrom] = useState(firstOfQuarter());
  const [to, setTo] = useState(lastOfQuarter());
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<Vat002Result | null>(null);
  const [csv, setCsv] = useState<string | null>(null);

  async function generate() {
    if (!isPaid) {
      toast.show(`Upgrade to Smart to export ${taxAuth} forms.`, { tone: 'warning' });
      return;
    }
    if (!isVat) {
      toast.show('Mark your business VAT-registered in Settings first.', { tone: 'warning' });
      return;
    }
    setLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke('generate-burs-vat-002', {
        body: { business_id: business.id, period_start: from, period_end: to },
      });
      if (error) throw error;
      setResult(data.result);
      setCsv(data.csv);
      toast.show(`${regionConfig.vat.returnForm} generated.`, { tone: 'success' });
    } catch (e) {
      toast.show(e instanceof Error ? e.message : 'Failed', { tone: 'error' });
    } finally {
      setLoading(false);
    }
  }

  function downloadCsv() {
    if (!csv) return;
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `vat002_${from}_to_${to}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  }

  return (
    <main className="mx-auto max-w-3xl px-4 py-4 md:px-6 md:py-6">
      <h1 className="font-display mb-4 flex items-center gap-2 text-2xl">
        <FileText size={22} /> {taxAuth} Tax Pack
      </h1>

      <div className="space-y-3">
        <Card>
          <div className="mb-3 flex items-start justify-between">
            <div>
              <h2 className="font-display text-lg">{regionConfig.vat.returnForm}</h2>
              <p className="text-muted text-sm">VAT return for {taxAuth}</p>
            </div>
            {isPaid ? (
              <Pill tone="green">Available</Pill>
            ) : (
              <Pill tone="neutral">
                <Lock size={10} className="mr-1 inline" /> Smart+
              </Pill>
            )}
          </div>

          <div className="mb-3 grid grid-cols-2 gap-2">
            <label className="flex flex-col gap-1 text-xs">
              From
              <input
                type="date"
                value={from}
                onChange={(e) => setFrom(e.target.value)}
                className="min-h-tap rounded-btn border-line border bg-white px-2"
              />
            </label>
            <label className="flex flex-col gap-1 text-xs">
              To
              <input
                type="date"
                value={to}
                onChange={(e) => setTo(e.target.value)}
                className="min-h-tap rounded-btn border-line border bg-white px-2"
              />
            </label>
          </div>

          <Button full onClick={generate} loading={loading} disabled={!isPaid || !isVat}>
            Generate VAT return
          </Button>

          {result && (
            <div className="border-line mt-4 space-y-2 border-t pt-4 text-sm">
              <Row label="Business" value={result.business_name} />
              <Row label="VAT number" value={result.vat_number ?? '—'} />
              <Row label="Period" value={`${result.period_start} → ${result.period_end}`} />
              <Row label="Output VAT" value={formatMoney(result.output_vat, regionCode)} bold />
              <Row label="Input VAT" value={formatMoney(result.input_vat, regionCode)} bold />
              <div className="border-line font-display flex justify-between border-t pt-2 text-base">
                <span>Net payable</span>
                <span
                  className={`tnum font-mono ${result.net_payable >= 0 ? 'text-red' : 'text-green'}`}
                >
                  {formatMoney(result.net_payable, regionCode)}
                </span>
              </div>
              <Button
                onClick={downloadCsv}
                leftIcon={<Download size={16} />}
                variant="secondary"
                full
              >
                Download CSV
              </Button>
            </div>
          )}
        </Card>

        <PayeCertificate
          businessId={business.id}
          businessName={business.name}
          tin={business.registration_no ?? null}
          isPaid={isPaid}
        />

        <IncomeTaxReturn
          businessId={business.id}
          businessName={business.name}
          tin={business.registration_no ?? null}
          fiscalStartMonth={business.fiscal_year_start_month}
          isPaid={isPaid}
        />
      </div>
    </main>
  );
}

function Row({ label, value, bold }: { label: string; value: string; bold?: boolean }) {
  return (
    <div className="flex justify-between">
      <span className="text-muted">{label}</span>
      <span className={bold ? 'tnum font-mono font-medium' : 'tnum font-mono'}>{value}</span>
    </div>
  );
}

function PayeCertificate({
  businessId,
  businessName,
  tin,
  isPaid,
}: {
  businessId: string;
  businessName: string;
  tin: string | null;
  isPaid: boolean;
}) {
  const regionCode = useRegionStore((s) => s.code);
  const regionConfig = useRegionStore((s) => s.config);
  const taxAuth = regionConfig.taxAuthority;
  const today = new Date();
  const [month, setMonth] = useState(today.getMonth());
  const [year, setYear] = useState(today.getFullYear());
  const [employees, setEmployees] = useState<PayeEmployee[]>([]);
  const [loading, setLoading] = useState(true);
  const toast = useToast();

  useEffect(() => {
    void (async () => {
      setLoading(true);
      const { data } = await supabase
        .from('employees')
        .select('id, name, national_id, basic_salary, allowances, deductions, is_active')
        .eq('business_id', businessId)
        .order('name');
      setEmployees((data ?? []) as PayeEmployee[]);
      setLoading(false);
    })();
  }, [businessId]);

  const rows: PayeRow[] = useMemo(() => {
    return employees
      .filter((e) => e.is_active)
      .map((e) => {
        const transport = e.allowances?.transport ?? 0;
        const housing = e.allowances?.housing ?? 0;
        const other = e.allowances?.other ?? 0;
        const gross = (e.basic_salary || 0) + transport + housing + other;
        const pension = e.deductions?.pension_employee ?? 0;
        const taxable = Math.max(0, gross - pension);
        const paye = monthlyPaye(taxable);
        return {
          name: e.name,
          national_id: e.national_id ?? '',
          gross: round2(gross),
          pension: round2(pension),
          taxable: round2(taxable),
          paye: round2(paye),
        };
      });
  }, [employees]);

  const totals = useMemo(() => {
    let gross = 0;
    let paye = 0;
    for (const r of rows) {
      gross += r.gross;
      paye += r.paye;
    }
    return { gross, paye };
  }, [rows]);

  function downloadCertificate() {
    if (!isPaid) {
      toast.show(`Upgrade to Smart to download ${taxAuth} certificates.`, { tone: 'warning' });
      return;
    }
    if (rows.length === 0) {
      toast.show('No active employees in payroll.', { tone: 'warning' });
      return;
    }
    const period = `${monthName(month)} ${year}`;
    const lines: string[] = [];
    lines.push('PAYE Certificate (Monthly Withholding Schedule)');
    lines.push(`Employer,${q(businessName)}`);
    lines.push(`${taxAuth} TIN / Reg No,${q(tin ?? 'NOT SET')}`);
    lines.push(`Period,${period}`);
    lines.push(`Generated,${new Date().toISOString().slice(0, 10)}`);
    lines.push('');
    lines.push(
      'Employee,National ID,Gross Earnings,Pension Deduction,Taxable Income,PAYE Withheld',
    );
    for (const r of rows) {
      lines.push([q(r.name), q(r.national_id), r.gross, r.pension, r.taxable, r.paye].join(','));
    }
    lines.push('');
    lines.push(`Totals,,${round2(totals.gross)},,,${round2(totals.paye)}`);

    const blob = new Blob([lines.join('\n')], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `paye_${year}_${monthName(month)}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    toast.show('PAYE certificate downloaded ✓', { tone: 'success' });
  }

  return (
    <Card>
      <div className="mb-3 flex items-start justify-between">
        <div>
          <h2 className="font-display flex items-center gap-2 text-lg">
            <UsersIcon size={18} /> PAYE Certificate
          </h2>
          <p className="text-muted text-sm">Monthly PAYE schedule for {taxAuth}</p>
        </div>
        {isPaid ? (
          <Pill tone="green">Available</Pill>
        ) : (
          <Pill tone="neutral">
            <Lock size={10} className="mr-1 inline" /> Smart+
          </Pill>
        )}
      </div>

      <div className="mb-3 grid grid-cols-2 gap-2">
        <label className="flex flex-col gap-1 text-xs">
          Month
          <select
            value={month}
            onChange={(e) => setMonth(Number(e.target.value))}
            className="min-h-tap rounded-btn border-line border bg-white px-2"
          >
            {Array.from({ length: 12 }).map((_, i) => (
              <option key={i} value={i}>
                {monthName(i)}
              </option>
            ))}
          </select>
        </label>
        <label className="flex flex-col gap-1 text-xs">
          Year
          <input
            type="number"
            value={year}
            onChange={(e) => setYear(Number(e.target.value))}
            className="min-h-tap rounded-btn border-line border bg-white px-2 font-mono"
          />
        </label>
      </div>

      {loading ? (
        <p className="text-muted text-sm">Loading employees…</p>
      ) : rows.length === 0 ? (
        <p className="text-muted py-3 text-sm">
          No active employees on payroll. Add employees in the Payroll module first.
        </p>
      ) : (
        <>
          <div className="border-line space-y-1 border-t pt-3 text-sm">
            <Row label="Employer" value={businessName} />
            <Row label={`${taxAuth} TIN / Reg No`} value={tin ?? '— not set —'} />
            <Row label="Period" value={`${monthName(month)} ${year}`} />
            <Row label="Active employees" value={String(rows.length)} />
            <Row label="Total gross" value={formatMoney(totals.gross, regionCode)} bold />
            <div className="border-line font-display flex justify-between border-t pt-2 text-base">
              <span>Total PAYE withheld</span>
              <span className="tnum text-red font-mono">
                {formatMoney(totals.paye, regionCode)}
              </span>
            </div>
          </div>

          <Button
            onClick={downloadCertificate}
            leftIcon={<Download size={16} />}
            variant="secondary"
            full
            className="mt-4"
            disabled={!isPaid}
          >
            Download PAYE certificate (CSV)
          </Button>
        </>
      )}
    </Card>
  );
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

// ───── Corporate Income Tax (annual return) ─────────────────────────
//
// GCC corporate tax varies by state: UAE 9% (0% under the AED 375k small-
// business threshold), Saudi 20% + 2.5% Zakat on the GCC-owned share,
// Qatar/Kuwait 15% / 10% on foreign-owned profit, Bahrain none (bar the
// DMTT for large MNEs), Oman 15% (3% for qualifying SMEs).
//
// Options are derived from the active region's config so the practice
// picks the right rate without us hard-coding a single jurisdiction.
// Uses buildProfitLoss across the fiscal year to compute net profit
// before tax, then applies the chosen rate.

interface TaxRateOption {
  id: string;
  label: string;
  rate: number;
}

function taxRateOptions(cfg: RegionConfig): TaxRateOption[] {
  const opts: TaxRateOption[] = [];
  const std = cfg.corporateTax.standard;
  opts.push({ id: 'standard', label: `Corporate Tax ${(std * 100).toFixed(0)}%`, rate: std });
  if (cfg.corporateTax.zakat) {
    opts.push({
      id: 'zakat',
      label: `Zakat ${(cfg.corporateTax.zakat * 100).toFixed(1)}% (GCC-owned)`,
      rate: cfg.corporateTax.zakat,
    });
  }
  if (cfg.corporateTax.small != null) {
    opts.push({
      id: 'small',
      label: `SME rate ${(cfg.corporateTax.small * 100).toFixed(0)}%`,
      rate: cfg.corporateTax.small,
    });
  }
  return opts;
}

function IncomeTaxReturn({
  businessId,
  businessName,
  tin,
  fiscalStartMonth,
  isPaid,
}: {
  businessId: string;
  businessName: string;
  tin: string | null;
  fiscalStartMonth: number;
  isPaid: boolean;
}) {
  const regionCode = useRegionStore((s) => s.code);
  const regionConfig = useRegionStore((s) => s.config);
  const taxAuth = regionConfig.taxAuthority;
  const TAX_RATE_OPTIONS = useMemo(() => taxRateOptions(regionConfig), [regionConfig]);
  const toast = useToast();
  const today = new Date();
  // Default to the most recently completed FY. If we are inside FY2026 (which
  // ends in month fiscalStartMonth-1), the most recent completed year is
  // FY2026 if today >= fiscalStartMonth, otherwise FY2025.
  const defaultYear =
    today.getMonth() + 1 >= fiscalStartMonth ? today.getFullYear() : today.getFullYear() - 1;

  const [year, setYear] = useState(defaultYear);
  const [rateId, setRateId] = useState<string>('standard');
  const [loading, setLoading] = useState(true);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [entries, setEntries] = useState<JournalEntry[]>([]);
  const [lines, setLines] = useState<JournalLine[]>([]);
  const [payeWithheld, setPayeWithheld] = useState(0);

  useEffect(() => {
    void (async () => {
      setLoading(true);
      const [a, e, l] = await Promise.all([
        supabase.from('accounts').select('*').eq('business_id', businessId),
        supabase.from('journal_entries').select('*').eq('business_id', businessId),
        supabase.from('journal_lines').select('*'),
      ]);
      setAccounts((a.data ?? []) as Account[]);
      setEntries((e.data ?? []) as JournalEntry[]);
      setLines((l.data ?? []) as JournalLine[]);
      setLoading(false);
    })();
  }, [businessId]);

  const period = useMemo(() => {
    // FY runs from fiscalStartMonth of (year-1) through fiscalStartMonth-1 of year.
    // Botswana standard FY is July-June, so fiscalStartMonth=7 → FY2026 = 1 Jul 2025 → 30 Jun 2026.
    const startMonthIdx = (fiscalStartMonth - 1 + 12) % 12;
    const startYear = year - 1;
    const start = new Date(startYear, startMonthIdx, 1);
    const end = new Date(year, startMonthIdx, 0); // last day of month before start
    return { start, end };
  }, [year, fiscalStartMonth]);

  const pl = useMemo(() => {
    if (loading) return null;
    return buildProfitLoss({ accounts, entries, lines }, period.start, period.end);
  }, [loading, accounts, entries, lines, period]);

  // Pull total PAYE already remitted via the payroll module across the year.
  useEffect(() => {
    if (loading) return;
    const startIso = period.start.toISOString().slice(0, 10);
    const endIso = period.end.toISOString().slice(0, 10);
    const payeAcct = accounts.find((a) => a.gl_code === '2200');
    if (!payeAcct) {
      setPayeWithheld(0);
      return;
    }
    const entryById = new Map(entries.map((e) => [e.id, e]));
    let total = 0;
    for (const line of lines) {
      if (line.account_id !== payeAcct.id) continue;
      const ent = entryById.get(line.entry_id);
      if (!ent) continue;
      if (ent.entry_date < startIso || ent.entry_date > endIso) continue;
      total += (Number(line.credit) || 0) - (Number(line.debit) || 0);
    }
    setPayeWithheld(total);
  }, [loading, accounts, entries, lines, period]);

  const rate = TAX_RATE_OPTIONS.find((r) => r.id === rateId)?.rate ?? regionConfig.corporateTax.standard;
  const chargeable = pl ? Math.max(0, pl.netProfit) : 0;
  const taxDue = round2(chargeable * rate);
  const balance = round2(taxDue - payeWithheld);

  function downloadIt14() {
    if (!isPaid) {
      toast.show(`Upgrade to Smart to download ${taxAuth} forms.`, { tone: 'warning' });
      return;
    }
    if (!pl) return;
    const fy = `FY${year}`;
    const periodLabel = `${period.start.toISOString().slice(0, 10)} to ${period.end
      .toISOString()
      .slice(0, 10)}`;

    const lines: string[] = [];
    lines.push('Corporate Income Tax Return (Annual)');
    lines.push(`Taxpayer,${q(businessName)}`);
    lines.push(`${taxAuth} TIN / Reg No,${q(tin ?? 'NOT SET')}`);
    lines.push(`Year of assessment,${fy}`);
    lines.push(`Period,${periodLabel}`);
    lines.push(`Generated,${new Date().toISOString().slice(0, 10)}`);
    lines.push('');
    lines.push('Section A — Income Statement Summary');
    lines.push(`Total income,${round2(pl.totalIncome)}`);
    lines.push(`Total expenses,${round2(pl.totalExpense)}`);
    lines.push(`Net profit before tax,${round2(pl.netProfit)}`);
    lines.push('');
    lines.push('Section B — Tax Computation');
    lines.push(
      `Applicable rate,${(TAX_RATE_OPTIONS.find((r) => r.id === rateId)?.label ?? '').replace(',', '')}`,
    );
    lines.push(`Chargeable income,${round2(chargeable)}`);
    lines.push(`Tax at ${(rate * 100).toFixed(0)}%,${taxDue}`);
    lines.push(`Less: PAYE already withheld,${round2(payeWithheld)}`);
    lines.push(
      `Balance ${balance >= 0 ? `PAYABLE TO ${taxAuth}` : `REFUNDABLE FROM ${taxAuth}`},${Math.abs(balance)}`,
    );

    const blob = new Blob([lines.join('\n')], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `it14_${fy}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    toast.show('IT14 downloaded ✓', { tone: 'success' });
  }

  return (
    <Card>
      <div className="mb-3 flex items-start justify-between">
        <div>
          <h2 className="font-display flex items-center gap-2 text-lg">
            <Landmark size={18} /> Income Tax IT14
          </h2>
          <p className="text-muted text-sm">Annual return for {taxAuth}</p>
        </div>
        {isPaid ? (
          <Pill tone="green">Available</Pill>
        ) : (
          <Pill tone="neutral">
            <Lock size={10} className="mr-1 inline" /> Smart+
          </Pill>
        )}
      </div>

      <div className="mb-3 grid grid-cols-2 gap-2">
        <label className="flex flex-col gap-1 text-xs">
          Year of assessment
          <input
            type="number"
            value={year}
            onChange={(e) => setYear(Number(e.target.value))}
            className="min-h-tap rounded-btn border-line border bg-white px-2 font-mono"
          />
        </label>
        <label className="flex flex-col gap-1 text-xs">
          Tax rate
          <select
            value={rateId}
            onChange={(e) => setRateId(e.target.value as (typeof TAX_RATE_OPTIONS)[number]['id'])}
            className="min-h-tap rounded-btn border-line border bg-white px-2"
          >
            {TAX_RATE_OPTIONS.map((r) => (
              <option key={r.id} value={r.id}>
                {r.label}
              </option>
            ))}
          </select>
        </label>
      </div>

      {loading ? (
        <p className="text-muted text-sm">Loading ledger…</p>
      ) : !pl ? (
        <p className="text-muted text-sm">No data.</p>
      ) : (
        <>
          <div className="border-line space-y-1 border-t pt-3 text-sm">
            <Row
              label="Period"
              value={`${period.start.toISOString().slice(0, 10)} → ${period.end
                .toISOString()
                .slice(0, 10)}`}
            />
            <Row label="Total income" value={formatMoney(pl.totalIncome, regionCode)} />
            <Row label="Total expenses" value={formatMoney(pl.totalExpense, regionCode)} />
            <div className="border-line flex justify-between border-t pt-2">
              <span className="font-medium">Net profit before tax</span>
              <span
                className={`tnum font-mono font-medium ${pl.netProfit >= 0 ? 'text-ink' : 'text-red'}`}
              >
                {formatMoney(pl.netProfit, regionCode)}
              </span>
            </div>
            <Row label="Chargeable income" value={formatMoney(chargeable, regionCode)} />
            <Row
              label={`Tax at ${(rate * 100).toFixed(0)}%`}
              value={formatMoney(taxDue, regionCode)}
              bold
            />
            <Row
              label="Less: PAYE already withheld"
              value={formatMoney(payeWithheld, regionCode)}
            />
            <div className="border-line font-display flex justify-between border-t pt-2 text-base">
              <span>
                {balance >= 0 ? `Balance payable to ${taxAuth}` : `Refund from ${taxAuth}`}
              </span>
              <span className={`tnum font-mono ${balance >= 0 ? 'text-red' : 'text-green'}`}>
                {formatMoney(Math.abs(balance), regionCode)}
              </span>
            </div>
          </div>

          <Button
            onClick={downloadIt14}
            leftIcon={<Download size={16} />}
            variant="secondary"
            full
            className="mt-4"
            disabled={!isPaid}
          >
            Download IT14 (CSV)
          </Button>

          <p className="text-muted mt-3 text-xs">
            Heads-up: this is a working draft. Have your accountant confirm before filing — most tax
            returns also need add-backs for non-deductible expenses (entertainment, donations over
            the cap, depreciation timing, etc.) which we don&apos;t auto-detect yet.
          </p>
        </>
      )}
    </Card>
  );
}

function q(s: string): string {
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

function firstOfQuarter(): string {
  const d = new Date();
  const q = Math.floor(d.getMonth() / 3);
  return new Date(d.getFullYear(), q * 3, 1).toISOString().slice(0, 10);
}
function lastOfQuarter(): string {
  const d = new Date();
  const q = Math.floor(d.getMonth() / 3);
  return new Date(d.getFullYear(), q * 3 + 3, 0).toISOString().slice(0, 10);
}
