// In-browser mock of the Supabase client surface we use.
//
// When `VITE_SUPABASE_URL` is empty, the real Supabase client is replaced with
// this mock so demo accounts work end-to-end on Prathap's laptop without ever
// touching the cloud. Data lives in localStorage and IndexedDB (image blobs).
//
// The shape only mimics the slice of `@supabase/supabase-js` that the app
// actually calls. New call sites need to extend this file in lockstep.

const LS_KEY = 'np.mock.db';
const LS_SESSION = 'np.mock.session';
const LS_VERSION = 'np.mock.seed_version';
// Bump when seedRifleClub / seedDental / seedRestaurant change so live users
// get fresh demo data on next page load.
const SEED_VERSION = '2026-05-21-dental-patients-recall';

interface MockSession {
  user: { id: string; email: string };
  access_token: 'mock';
  refresh_token: 'mock';
  expires_in: 3600;
  token_type: 'bearer';
}

type Table =
  | 'profiles'
  | 'businesses'
  | 'accounts'
  | 'journal_entries'
  | 'journal_lines'
  | 'receipts'
  | 'invoices'
  | 'invoice_payments'
  | 'inventory_items'
  | 'fixed_assets'
  | 'customers'
  | 'suppliers'
  | 'employees'
  | 'reminders'
  | 'merchants'
  | 'audit_log'
  | 'user_telegram'
  // Healthcare / dental patient management (mirror of 0009_patient_management.sql).
  | 'patients'
  | 'patient_visits'
  | 'patient_prescriptions'
  | 'patient_audit_log';

interface DB {
  users: Array<{ id: string; email: string; password: string }>;
  profiles: any[];
  businesses: any[];
  accounts: any[];
  journal_entries: any[];
  journal_lines: any[];
  receipts: any[];
  invoices: any[];
  invoice_payments: any[];
  inventory_items: any[];
  fixed_assets: any[];
  customers: any[];
  suppliers: any[];
  employees: any[];
  reminders: any[];
  merchants: any[];
  audit_log: any[];
  user_telegram: any[];
  patients: any[];
  patient_visits: any[];
  patient_prescriptions: any[];
  patient_audit_log: any[];
}

function emptyDb(): DB {
  return {
    users: [],
    profiles: [],
    businesses: [],
    accounts: [],
    journal_entries: [],
    journal_lines: [],
    receipts: [],
    invoices: [],
    invoice_payments: [],
    inventory_items: [],
    fixed_assets: [],
    customers: [],
    suppliers: [],
    employees: [],
    reminders: [],
    merchants: [],
    audit_log: [],
    user_telegram: [],
    patients: [],
    patient_visits: [],
    patient_prescriptions: [],
    patient_audit_log: [],
  };
}

function load(): DB {
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (!raw) return emptyDb();
    return { ...emptyDb(), ...JSON.parse(raw) };
  } catch {
    return emptyDb();
  }
}

function save(db: DB) {
  localStorage.setItem(LS_KEY, JSON.stringify(db));
}

// On seed-version bump, wipe stored mock DB + session so users see fresh data.
try {
  const stored = localStorage.getItem(LS_VERSION);
  if (stored !== SEED_VERSION) {
    localStorage.removeItem(LS_KEY);
    localStorage.removeItem(LS_SESSION);
    localStorage.setItem(LS_VERSION, SEED_VERSION);
  }
} catch {
  // localStorage unavailable; carry on with in-memory.
}

let _db = load();
let _session: MockSession | null = (() => {
  try {
    const raw = localStorage.getItem(LS_SESSION);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
})();

const authListeners: Array<(event: string, session: MockSession | null) => void> = [];
function notifyAuth(event: string) {
  for (const fn of authListeners) fn(event, _session);
}

