function uuid(): string {
  return crypto.randomUUID();
}

function postSimple(
  bizId: string,
  userId: string,
  date: string,
  description: string,
  drAccountId: string,
  crAccountId: string,
  amount: number,
) {
  const eid = uuid();
  _db.journal_entries.push({
    id: eid,
    business_id: bizId,
    entry_date: date,
    reference: description,
    description,
    source: 'manual',
    source_id: null,
    is_posted: true,
    is_locked: false,
    posted_at: new Date().toISOString(),
    created_by: userId,
    created_at: new Date().toISOString(),
  });
  _db.journal_lines.push(
    {
      id: uuid(),
      entry_id: eid,
      account_id: drAccountId,
      debit: amount,
      credit: 0,
      vat_amount: 0,
      vat_rate: 0,
      description,
    },
    {
      id: uuid(),
      entry_id: eid,
      account_id: crAccountId,
      debit: 0,
      credit: amount,
      vat_amount: 0,
      vat_rate: 0,
      description,
    },
  );
}

function ensureAccount(
  bizId: string,
  glCode: string,
  name: string,
  type: 'asset' | 'liability' | 'equity' | 'income' | 'expense',
): string {
  const existing = _db.accounts.find((a) => a.business_id === bizId && a.gl_code === glCode);
  if (existing) return existing.id;
  const id = uuid();
  _db.accounts.push({
    id,
    business_id: bizId,
    gl_code: glCode,
    name,
    type,
    parent_id: null,
    is_active: true,
    is_system: true,
    created_at: new Date().toISOString(),
  });
  return id;
}

