// ============================================================
// Query builder
// ============================================================

interface Filter {
  op: 'eq' | 'neq' | 'gt' | 'gte' | 'lt' | 'lte' | 'in' | 'is';
  col: string;
  val: any;
}

class QueryBuilder<T = any> {
  private _filters: Filter[] = [];
  private _order: { col: string; ascending: boolean } | null = null;
  private _limit: number | null = null;
  private _single = false;
  private _maybeSingle = false;
  private _action: 'select' | 'insert' | 'update' | 'delete' | 'upsert' = 'select';
  private _payload: any = null;

  constructor(private table: Table) {}

  select(_cols?: string): this {
    this._action = this._action === 'insert' || this._action === 'update' ? this._action : 'select';
    return this;
  }
  insert(payload: any): this {
    this._action = 'insert';
    this._payload = payload;
    return this;
  }
  update(payload: any): this {
    this._action = 'update';
    this._payload = payload;
    return this;
  }
  upsert(payload: any): this {
    this._action = 'upsert';
    this._payload = payload;
    return this;
  }
  delete(): this {
    this._action = 'delete';
    return this;
  }

  eq(col: string, val: any): this {
    this._filters.push({ op: 'eq', col, val });
    return this;
  }
  neq(col: string, val: any): this {
    this._filters.push({ op: 'neq', col, val });
    return this;
  }
  gt(col: string, val: any): this {
    this._filters.push({ op: 'gt', col, val });
    return this;
  }
  gte(col: string, val: any): this {
    this._filters.push({ op: 'gte', col, val });
    return this;
  }
  lt(col: string, val: any): this {
    this._filters.push({ op: 'lt', col, val });
    return this;
  }
  lte(col: string, val: any): this {
    this._filters.push({ op: 'lte', col, val });
    return this;
  }
  in(col: string, vals: any[]): this {
    this._filters.push({ op: 'in', col, val: vals });
    return this;
  }
  is(col: string, val: any): this {
    this._filters.push({ op: 'is', col, val });
    return this;
  }

  order(col: string, opts?: { ascending?: boolean }): this {
    this._order = { col, ascending: opts?.ascending ?? true };
    return this;
  }

  limit(n: number): this {
    this._limit = n;
    return this;
  }
  single(): Promise<{ data: T | null; error: any }> {
    this._single = true;
    return this._exec();
  }
  maybeSingle(): Promise<{ data: T | null; error: any }> {
    this._maybeSingle = true;
    return this._exec();
  }

  then<TResult1 = { data: T[] | T | null; error: any }, TResult2 = never>(
    onFulfilled?:
      | ((value: { data: T[] | T | null; error: any }) => TResult1 | PromiseLike<TResult1>)
      | null,
    onRejected?: ((reason: any) => TResult2 | PromiseLike<TResult2>) | null,
  ): Promise<TResult1 | TResult2> {
    return this._exec().then(onFulfilled as any, onRejected) as any;
  }

  private match(row: any): boolean {
    for (const f of this._filters) {
      const cell = row[f.col];
      switch (f.op) {
        case 'eq':
          if (cell !== f.val) return false;
          break;
        case 'neq':
          if (cell === f.val) return false;
          break;
        case 'gt':
          if (!(cell > f.val)) return false;
          break;
        case 'gte':
          if (!(cell >= f.val)) return false;
          break;
        case 'lt':
          if (!(cell < f.val)) return false;
          break;
        case 'lte':
          if (!(cell <= f.val)) return false;
          break;
        case 'in':
          if (!Array.isArray(f.val) || !f.val.includes(cell)) return false;
          break;
        case 'is':
          if (cell !== f.val) return false;
          break;
      }
    }
    return true;
  }

  private async _exec(): Promise<{ data: any; error: any }> {
    try {
      const list = (_db as any)[this.table] as any[];
      if (!Array.isArray(list))
        return { data: null, error: { message: `unknown table ${this.table}` } };

      if (this._action === 'select') {
        let rows = list.filter((r) => this.match(r));
        if (this._order) {
          const o = this._order;
          rows = [...rows].sort((a, b) => {
            const av = a[o.col];
            const bv = b[o.col];
            if (av === bv) return 0;
            if (av == null) return 1;
            if (bv == null) return -1;
            return o.ascending ? (av < bv ? -1 : 1) : av < bv ? 1 : -1;
          });
        }
        if (this._limit != null) rows = rows.slice(0, this._limit);
        if (this._single) {
          if (rows.length !== 1)
            return { data: null, error: { message: 'expected single row', code: 'PGRST116' } };
          return { data: rows[0], error: null };
        }
        if (this._maybeSingle) return { data: rows[0] ?? null, error: null };
        return { data: rows, error: null };
      }

      if (this._action === 'insert') {
        const items = Array.isArray(this._payload) ? this._payload : [this._payload];
        const inserted: any[] = [];
        for (const item of items) {
          const row = {
            id: item.id ?? uuid(),
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
            ...item,
          };
          list.push(row);
          inserted.push(row);
        }
        save(_db);
        if (this._single) return { data: inserted[0], error: null };
        if (this._maybeSingle) return { data: inserted[0] ?? null, error: null };
        return { data: inserted, error: null };
      }

      if (this._action === 'update') {
        const updated: any[] = [];
        for (let i = 0; i < list.length; i++) {
          if (this.match(list[i])) {
            list[i] = { ...list[i], ...this._payload, updated_at: new Date().toISOString() };
            updated.push(list[i]);
          }
        }
        save(_db);
        if (this._single) return { data: updated[0] ?? null, error: null };
        if (this._maybeSingle) return { data: updated[0] ?? null, error: null };
        return { data: updated, error: null };
      }

      if (this._action === 'delete') {
        const before = list.length;
        const remaining = list.filter((r) => !this.match(r));
        (_db as any)[this.table] = remaining;
        save(_db);
        return { data: { deleted: before - remaining.length }, error: null };
      }

      return { data: null, error: { message: `unsupported action ${this._action}` } };
    } catch (e: any) {
      return { data: null, error: { message: e?.message ?? String(e) } };
    }
  }
}

